import {
  canParticipateChannel,
  isChannelInvitation,
} from "../channelPermissions";
import type { TFunction } from "i18next";
import type {
  AccountInfo,
  ChannelInfo,
  FavoriteInfo,
  PeerInfo,
  PresenceMap,
} from "@/lib/types";
import { isContactPeer, peerAccountKey } from "@/lib/rosterProjection";
import { displayIdentity } from "@/lib/displayIdentity";
import type { Conversation } from "@/store/chat";

/** The same row contract drives pinned, ordinary and virtualized sections. */
export interface ConversationListRow {
  id: string;
  conv: Conversation;
  pinned: boolean;
  channel: boolean;
  subtitle: string;
  prioritizeSubtitle: boolean;
  personal?: boolean;
  deletable?: boolean;
  /** Rename edits the announced name, not the displayed personal alias. */
  renameName: string;
}

type Favorites = Readonly<
  Record<string, Pick<FavoriteInfo, "pinned" | "custom_alias" | "hidden">>
>;

/** Pure projection: stable source order within pins, contacts, groups and restoration. */
export function conversationList(
  accounts: readonly AccountInfo[],
  channels: readonly ChannelInfo[],
  favorites: Favorites,
  t: TFunction,
  ownAccount?: string,
  personalReady = true,
) {
  const pinnedRows: ConversationListRow[] = [];
  const accountRows: ConversationListRow[] = [];
  const channelRows: ConversationListRow[] = [];
  const hiddenChannels: ConversationListRow[] = [];
  const previousAccountRows: ConversationListRow[] = [];
  if (ownAccount && personalReady) {
    accountRows.push({
      id: ownAccount,
      conv: { kind: "account", id: ownAccount, name: t("personal.title") },
      renameName: t("personal.title"),
      channel: false,
      personal: true,
      pinned: false,
      subtitle: t("personal.description"),
      prioritizeSubtitle: false,
    });
  }
  for (const a of accounts) {
    const id = a.account_id;
    if (id === ownAccount) continue;
    const identity = displayIdentity({ accountId: id, accounts, favorites });
    const renameName = identity.canonicalName;
    const row: ConversationListRow = {
      id,
      renameName,
      channel: false,
      conv: {
        kind: "account",
        id,
        name: identity.name,
      },
      pinned: favorites[id]?.pinned ?? false,
      subtitle: t("sidebar.devices", { count: a.device_count }),
      prioritizeSubtitle: false,
    };
    (row.pinned ? pinnedRows : accountRows).push(row);
  }
  for (const c of channels) {
    const id = c.channel_id;
    const participant = canParticipateChannel(c);
    const access = c.account_access;
    const roleKnown = access !== undefined;
    const accessPending = roleKnown && (!access || access.role === "unknown");
    const referenceOnly = c.shared_reference && !roleKnown;
    const dissolved = roleKnown ? access?.role === "dissolved" : c.dissolved;
    const archived = !roleKnown && c.archived;
    const left = roleKnown ? access?.role === "left" : c.left;
    const lifecycleCaption = c.previous_account
      ? t("conversation.previousAccountChannel")
      : participant
        ? null
        : accessPending
          ? t("conversation.groupAccessPending", {
              defaultValue: "Updating group access…",
            })
          : referenceOnly
            ? t("conversation.sharedReference")
            : dissolved
              ? t("conversation.dissolvedChannel")
              : archived
                ? t("conversation.archivedChannel")
                : left
                  ? t("conversation.leftChannel")
                  : isChannelInvitation(c)
                    ? t("conversation.pendingInvite")
                    : null;
    const row: ConversationListRow = {
      id,
      channel: true,
      renameName: c.name,
      deletable: !c.previous_account && (left || dissolved),
      conv: {
        kind: "channel",
        id,
        name: favorites[id]?.custom_alias || c.name,
      },
      pinned: !c.previous_account && (favorites[id]?.pinned ?? false),
      subtitle:
        lifecycleCaption ??
        t("conversation.members", { count: c.member_count }),
      prioritizeSubtitle: lifecycleCaption !== null,
    };
    if (c.previous_account && !favorites[id]?.hidden) {
      previousAccountRows.push(row);
      continue;
    }
    (favorites[id]?.hidden
      ? hiddenChannels
      : row.pinned
        ? pinnedRows
        : channelRows
    ).push(row);
  }
  return {
    pinnedRows,
    accountRows,
    channelRows,
    hiddenChannels,
    previousAccountRows,
    listSize: pinnedRows.length + accountRows.length + channelRows.length,
  };
}

/** Hidden people still prevent a misleading "stranded" prompt; relays never count. */
export function sidebarPeopleCounts(
  peers: readonly PeerInfo[],
  presence: PresenceMap,
  ownAccount: string | null,
  hidden: Readonly<Record<string, unknown>>,
  policyLoaded: boolean,
) {
  const network = new Set<string>();
  const visible = new Set<string>();
  for (const peer of peers) {
    if (!isContactPeer(peer)) continue;
    const account = peerAccountKey(peer);
    if (account === ownAccount || !presence[account]?.online) continue;
    network.add(account);
    if (policyLoaded && !hidden[account]) visible.add(account);
  }
  return { networkPeople: network.size, onlinePeople: visible.size };
}

use super::{NodeState, PeerInfo};
use crate::{commands::CommandError, runtime_admission::RuntimeAdmission, state::AppState};
use serde::Serialize;

#[tauri::command]
pub async fn my_id(state: tauri::State<'_, NodeState>) -> Result<String, CommandError> {
    let guard = state.0.read().await;
    let rt = guard.as_ref().ok_or_else(CommandError::not_started)?;
    Ok(rt.user_id().to_string())
}

#[tauri::command]
pub async fn list_peers(state: tauri::State<'_, NodeState>) -> Result<Vec<PeerInfo>, CommandError> {
    list_peers_with_snapshot(&state, |node| async move {
        node.cached_peer_snapshot_async().await
    })
    .await
}

async fn list_peers_with_snapshot<F, Fut>(
    state: &NodeState,
    snapshot: F,
) -> Result<Vec<PeerInfo>, CommandError>
where
    F: FnOnce(std::sync::Arc<mesh_talk_core::node::Node>) -> Fut,
    Fut: std::future::Future<
            Output = std::io::Result<Vec<mesh_talk_core::discovery::roster::PeerRecord>>,
        >,
{
    let node = {
        let guard = state.0.read().await;
        let rt = guard.as_ref().ok_or_else(CommandError::not_started)?;
        if !rt.discovery_available() {
            return Err(CommandError::Internal("discovery unavailable".into()));
        }
        rt.handle()
    };
    // Core owns the blocking persistence and its retirement permit. The runtime
    // slot stays available for installation and unrelated session operations.
    let peers = snapshot(node.clone())
        .await
        .map_err(|error| CommandError::Io(error.to_string()))?;
    let guard = state.0.read().await;
    let rt = guard.as_ref().ok_or_else(CommandError::not_started)?;
    if !rt.discovery_available() || !std::sync::Arc::ptr_eq(&rt.handle(), &node) {
        return Err(CommandError::not_started());
    }
    Ok(peers.into_iter().map(PeerInfo::from).collect())
}

#[tauri::command]
pub async fn account_id(state: tauri::State<'_, NodeState>) -> Result<String, CommandError> {
    let guard = state.0.read().await;
    let rt = guard.as_ref().ok_or_else(CommandError::not_started)?;
    Ok(rt.account_id().to_string())
}

/// Publish (or clear) this user's OWN avatar to peers as a signed profile. Called by the
/// frontend when the user sets/removes their own photo (the local `avatars.json` mirror is
/// still written by `set_avatar` so the override-precedence logic is unchanged). `avatar`
/// is the small data-URL string; `None` clears it (propagates a "no avatar"). The node
/// bounds the size and signs it with the account key.
#[tauri::command]
pub async fn publish_avatar(
    app: tauri::State<'_, AppState>,
    state: tauri::State<'_, NodeState>,
    owner: String,
    expected_account: String,
    avatar: REDACTED,
) -> Result<(), CommandError> {
    let admission = RuntimeAdmission::capture(&app, &state, &owner)?;
    admission
        .detached(move |runtime, admission| {
            Box::pin(async move {
                let node = runtime.handle();
                node.set_avatar_if(avatar.map(|s| s.into_bytes()), |commit| {
                    admission.authorize_accept(runtime, &mut || {
                        if runtime.account_id() != expected_account {
                            return Err(mesh_talk_core::node::NodeError::Authorization(
                                "avatar account changed".into(),
                            ));
                        }
                        commit()
                    })
                })
                .await
                .map_err(CommandError::from)
            })
        })
        .await
}

/// One current signed avatar, including a clear tombstone, under the same
/// owner admission as profile edits. No whole-profile map crosses IPC.
#[tauri::command]
pub async fn peer_profile_avatar(
    app: tauri::State<'_, crate::state::AppState>,
    state: tauri::State<'_, NodeState>,
    owner: String,
    account_id: String,
) -> Result<Option<crate::events::ProfileReceivedEvent>, CommandError> {
    let admission = RuntimeAdmission::capture(&app, &state, &owner)?;
    if account_id.len() != 32 || hex::decode(&account_id).is_err() {
        return Err(CommandError::Validation("invalid mesh account ID".into()));
    }
    admission
        .blocking(move |runtime, _| {
            Ok(runtime
                .handle()
                .current_profile(&account_id)?
                .map(|profile| crate::events::ProfileReceivedEvent {
                    account_id: profile.account_id,
                    avatar: profile
                        .avatar
                        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned()),
                }))
        })
        .await
}

async fn prepare_linking_sync(
    admission: &RuntimeAdmission,
    sync_all: Option<bool>,
) -> Result<(), CommandError> {
    if sync_all == Some(true) {
        admission
            .with_runtime(|runtime| {
                use mesh_talk_core::node::SyncCategory;
                let node = runtime.handle();
                for category in [
                    SyncCategory::History,
                    SyncCategory::Attachments,
                    SyncCategory::Profile,
                    SyncCategory::Appearance,
                    SyncCategory::Contacts,
                ] {
                    node.set_device_sync_category(category, true)?;
                }
                Ok(())
            })
            .await?;
    }
    Ok(())
}

#[tauri::command]
pub async fn start_linking<R: tauri::Runtime>(
    handle: tauri::AppHandle<R>,
    app: tauri::State<'_, AppState>,
    state: tauri::State<'_, NodeState>,
    password: REDACTED,
    sync_all: Option<bool>,
) -> Result<String, CommandError> {
    let admission = RuntimeAdmission::capture_current(&app, &state)?
        .verify_identity(password, "link a Mesh-Talk device")
        .await?;
    prepare_linking_sync(&admission, sync_all).await?;
    let source_app = app.inner().clone();
    admission
        .clone()
        .detached(move |rt, admission| {
            Box::pin(async move {
                crate::shared_account_login::initialize_source(&source_app, admission, rt)?;
                if rt.handle().account_profile(rt.account_id())?.is_none() {
                    rt.handle()
                        .set_profile_display_name(&rt.display_name())
                        .map_err(CommandError::from)?;
                }
                Ok(())
            })
        })
        .await?;
    crate::shared_account_login::apply_current(
        handle,
        crate::data_dir(),
        app.inner().clone(),
        state.inner().clone(),
        admission.clone(),
    )
    .await?;
    admission.with_runtime(|rt| Ok(rt.start_linking())).await
}

#[tauri::command]
pub async fn stop_linking(
    app: tauri::State<'_, AppState>,
    state: tauri::State<'_, NodeState>,
) -> Result<(), CommandError> {
    RuntimeAdmission::capture_current(&app, &state)?
        .with_runtime(move |rt| {
            rt.stop_linking();
            Ok(())
        })
        .await
}

#[tauri::command]
pub async fn link_device(
    app: tauri::State<'_, AppState>,
    state: tauri::State<'_, NodeState>,
    peer: String,
    code: String,
    password: REDACTED,
    sync_all: Option<bool>,
) -> Result<String, CommandError> {
    let admission = RuntimeAdmission::capture_current(&app, &state)?
        .verify_identity(password, "link a Mesh-Talk device")
        .await?;
    prepare_linking_sync(&admission, sync_all).await?;
    let app = app.inner().clone();
    admission
        .detached(move |runtime, admission| {
            Box::pin(async move {
                let rt = runtime;
                rt.link_device_with_account_access_checked_if(
                    &peer,
                    &code,
                    |snapshot| {
                        crate::shared_account_login::preflight(
                            &crate::data_dir(),
                            &app,
                            admission,
                            runtime,
                            snapshot,
                        )
                    },
                    |commit| admission.authorize_accept(runtime, commit),
                )
                .await
                .map_err(CommandError::from)
            })
        })
        .await
}

#[tauri::command]
pub async fn rekey_account(
    app: tauri::State<'_, AppState>,
    state: tauri::State<'_, NodeState>,
) -> Result<String, CommandError> {
import type { ChannelMemberInfo, PeerInfo } from "./types";

/** Infrastructure remains in the raw roster for routing and diagnostics. */
export function isContactPeer(peer: Pick<PeerInfo, "post_office">): boolean {
  return !peer.post_office;
}

/** Account-scoped presentation key, with a legacy device fallback. */
export function peerAccountKey(
  peer: Pick<PeerInfo, "account_id" | "user_id">,
): string {
  return peer.account_id ?? peer.user_id;
}

/** Current roster lookups. Channel membership and offline history have separate owners. */
export interface RosterProjection {
  peerForDevice(deviceId: string): PeerInfo | undefined;
  accountForDevice(deviceId: string): string | null;
  nameForDevice(deviceId: string): string | null;
  /** An ordinary device with an advertised account binding. */
  contactForAccount(accountId: string): PeerInfo | undefined;
  devicesForAccount(accountId: string): readonly PeerInfo[];
  contactDevicesForAccount(accountId: string): readonly PeerInfo[];
  accountForMember(
    member: Pick<ChannelMemberInfo, "user_id" | "account_id">,
  ): string | null;
}

// Zustand replaces roster arrays on change. Reusing the projection for an unchanged
// array keeps message-row lookups cheap and gives all UI surfaces the same snapshot.
const cache = new WeakMap<readonly PeerInfo[], RosterProjection>();

export function rosterProjection(peers: readonly PeerInfo[]): RosterProjection {
  const cached = cache.get(peers);
  if (cached) return cached;

  const byDevice = new Map<string, PeerInfo>();
  const contactByAccount = new Map<string, PeerInfo>();
  const byAccount = new Map<string, PeerInfo[]>();
  const contactDevicesByAccount = new Map<string, PeerInfo[]>();
  for (const peer of peers) {
    if (!byDevice.has(peer.user_id)) byDevice.set(peer.user_id, peer);
    if (
      peer.account_id &&
      isContactPeer(peer) &&
      !contactByAccount.has(peer.account_id)
    )
      contactByAccount.set(peer.account_id, peer);
    if (peer.account_id) {
      const devices = byAccount.get(peer.account_id) ?? [];
      devices.push(peer);
      byAccount.set(peer.account_id, devices);
      if (isContactPeer(peer)) {
        const contacts = contactDevicesByAccount.get(peer.account_id) ?? [];
        contacts.push(peer);
        contactDevicesByAccount.set(peer.account_id, contacts);
      }
    }
  }

  const projection: RosterProjection = {
    peerForDevice: (deviceId) => byDevice.get(deviceId),
    accountForDevice: (deviceId) => byDevice.get(deviceId)?.account_id ?? null,
    nameForDevice: (deviceId) => byDevice.get(deviceId)?.name || null,
    contactForAccount: (accountId) => contactByAccount.get(accountId),
    devicesForAccount: (accountId) => byAccount.get(accountId) ?? [],
    contactDevicesForAccount: (accountId) =>
      contactDevicesByAccount.get(accountId) ?? [],
    // A channel snapshot can retain its signed account binding after discovery expires.
    accountForMember: (member) =>
      member.account_id ?? byDevice.get(member.user_id)?.account_id ?? null,
  };
  cache.set(peers, projection);
  return projection;
}

