#[derive(Serialize)]
pub struct RosterObservation {
    identity: NodeIdentity,
    peers: Vec<crate::chat_commands::PeerInfo>,
    people: std::collections::HashMap<String, crate::chat_commands::PresenceInfo>,
}

/// One authorized discovery read; group metadata and bodies have separate owners.
#[tauri::command]
pub async fn owner_roster_observation(
    owner: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<RosterObservation, CommandError> {
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    roster_observation_with_snapshot(&admission, &node, owner, |handle| async move {
        handle.cached_peer_snapshot_async().await
    })
    .await
}

async fn roster_observation_with_snapshot<F, Fut>(
    admission: &RuntimeAdmission,
    node: &NodeState,
    owner: String,
    snapshot: F,
) -> Result<RosterObservation, CommandError>
where
    F: FnOnce(std::sync::Arc<mesh_talk_core::node::Node>) -> Fut,
    Fut: std::future::Future<
            Output = std::io::Result<Vec<mesh_talk_core::discovery::roster::PeerRecord>>,
        >,
{
    let handle = admission
        .with_runtime(|runtime| {
            if !runtime.discovery_available() {
                return Err(CommandError::Internal("discovery unavailable".into()));
            }
            Ok(runtime.handle())
        })
        .await?;
    let peers = snapshot(handle.clone()).await;
    admission
        .with_runtime(|runtime| {
            if !runtime.discovery_available() || !std::sync::Arc::ptr_eq(&runtime.handle(), &handle)
            {
                return Err(CommandError::not_started());
            }
            let peers = peers.map_err(|error| CommandError::Io(error.to_string()))?;
            let people = crate::chat_commands::project_people(runtime, &peers);
            Ok(RosterObservation {
                identity: NodeIdentity {
                    owner,
                    device_id: runtime.user_id().into(),
                    account_id: runtime.account_id().into(),
                    display_name: runtime.display_name(),
                    history_revision: runtime.account_history_revision(),
                    supports_push_state: true,
                    supports_bounded_delivery: runtime.handle().bounded_delivery(),
                    runtime_id: node.installed_runtime_id(admission.lease())?,
                },
                peers: peers
                    .into_iter()
                    .map(crate::chat_commands::PeerInfo::from)
                    .collect(),
                people,
            })
        })
        .await
}

#[derive(Serialize)]
#[serde(untagged)]
pub enum ConditionalPresence {
    Unchanged { unchanged: bool },
    Full(crate::chat_commands::PresenceResponse),
}

#[tauri::command]
pub async fn owner_presence_if_groups_changed(
    owner: String,
    known_group_revision: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<ConditionalPresence, CommandError> {
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    presence_if_groups_changed(&admission, &known_group_revision, || {
        crate::chat_commands::get_presence_for_state(&node, Some(String::new()))
    })
    .await
}

async fn presence_if_groups_changed<F, Fut>(
    admission: &RuntimeAdmission,
    known_group_revision: &str,
    refresh: F,
) -> Result<ConditionalPresence, CommandError>
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future<Output = Result<crate::chat_commands::PresenceResponse, CommandError>>,
{
    presence_if_groups_changed_with_revision(
        admission,
        known_group_revision,
        |node, work| group_revision_with_work(node, work, |node| node.group_projection_revision()),
        refresh,
    )
    .await
}

async fn group_revision_with_work(
    node: std::sync::Arc<mesh_talk_core::node::Node>,
    work: mesh_talk_core::node::ParticipantWork,
    read: impl FnOnce(
        std::sync::Arc<mesh_talk_core::node::Node>,
    ) -> Result<[u8; 32], mesh_talk_core::eventlog::LogError>
    + Send
    + 'static,
) -> Result<String, CommandError> {
    let mut tasks = tokio::task::JoinSet::new();
    if !work.spawn(&mut tasks, move || read(node)) {
          user: state.user
            ? { ...state.user, display_name: identity.display_name! }
            : null,
        }));
    }
    if (!publishedAccountRoster?.current()) publishedAccountRoster = null;
    // Keep full reads concurrent. Heartbeats first inspect cheap discovery facts;
    // route-only changes still publish peers without rereading account history/policy.
    const observedPeers = presenceOnly
      ? ticket
        ? await ticket.read(lease.owner!).then(({ value }) => {
            if (
              value.identity.owner !== lease.owner ||
              value.identity.account_id !== identity.account_id ||
              value.identity.device_id !== identity.device_id ||
              value.identity.runtime_id !== identity.runtime_id
            )
              throw new Error("Roster source identity changed");
            return value.peers;
          })
        : await readWithDeadline(() => chat.listPeers())
      : null;
    if (!lease.current() || get().rosterRequest !== request || hasPending())
      return;
    const reuseAccounts =
      presenceOnly &&
      publishedAccountRoster?.current() &&
      publishedAccountRoster.projection ===
        accountRosterProjection(observedPeers!);
    const [peersSnapshot, listedAccounts, personal] = await Promise.all([
      observedPeers === null
        ? readWithDeadline(() => chat.listPeers())
        : Promise.resolve(observedPeers),
      reuseAccounts
        ? Promise.resolve(null)
        : readWithDeadline(() => chat.listAccounts()),
      presenceOnly
        ? Promise.resolve(null)
        : readWithDeadline(() =>
            chat.personalConversationStates(lease.owner!, identity.account_id),
          ).catch(() => null),
    ]);
    if (!lease.current() || get().rosterRequest !== request || hasPending())
      return;
    const personalEffects = applyPersonalConversationStates(
      rawSet,
      get,
      lease,
      personal,
    );
    // Full state work can wait on personal documents after its roster facts
    // were read. Keep any newer published presence while still applying those
    // personal documents and continuing the full history reconciliation.
    const publishObservation = observation >= publishedRosterObservation;
    // Reusing accounts only observes presence. It must not supersede a pending
    // full account read of durable metadata independent of discovery facts.
    const publishAccounts =
      listedAccounts !== null &&
      (!publishedAccountRoster?.current() ||
        observation >= publishedAccountRoster.observation);
    const peers = publishObservation ? peersSnapshot : get().peers;
    const accounts = (
      publishAccounts && listedAccounts !== null
        ? listedAccounts
        : get().accounts
    ).filter((account) => {
      const personal =
        get().personalConversationStates[`account:${account.account_id}`];
      return !(personal?.hidden && personal.local_cleanup_complete);
    });
    setPushStateSupport(identity.supports_push_state ? lease.owner : null);
    const channelWork = presenceOnly
      ? Promise.resolve()
      : personalEffects.changed
        ? channelRefresh.invalidate()
        : channelRefresh.ifDue();
    // Polling returns fresh arrays even when discovery has not changed. Preserve
    // the previous references so sidebar subscribers do not redraw every tick.
    if (publishObservation) publishedRosterObservation = observation;
    if (publishAccounts)
      publishedAccountRoster = {
        projection: accountRosterProjection(peersSnapshot),
        observation,
        current: lease.current,
      };
    const previous = get();
    const rosterChanged =
      JSON.stringify([previous.peers, previous.accounts]) !==
      JSON.stringify([peers, accounts]);
    const resolved = peers.filter(
      (peer) => peer.account_id && previous.pendingUnknownUnread[peer.user_id],
    );
    if (rosterChanged || resolved.length) {
      const unread = { ...previous.unread };
      const pendingUnknownUnread = { ...previous.pendingUnknownUnread };
      for (const peer of resolved) {
        const key = `account:${peer.account_id}`;
        unread[key] = (unread[key] ?? 0) + pendingUnknownUnread[peer.user_id];
        delete pendingUnknownUnread[peer.user_id];
      }
      set({
        ...(rosterChanged ? { peers, accounts } : {}),
        ...(resolved.length ? { unread, pendingUnknownUnread } : {}),
      });
    }
    if (presenceOnly) return;
    await channelWork;
    if (!lease.current() || get().rosterRequest !== request || hasPending())
      return;
    const channels = get().channels;
    refreshChannelRecovery(rawSet, get);
    if (personalEffects.reloadActive && get().active) await get().reload();
    if (!lease.current() || get().rosterRequest !== request || hasPending())
      return;
    if (identity.history_revision !== undefined) {
      await scanConversationHistory(
        rawSet,
        get,
        [
          // Saved Messages belongs to the runtime even when the contact
          // directory has no row for our own account.
          ...Array.from(
            new Set([
              ...accounts.map((account) => account.account_id),
              identity.account_id,
            ]),
          ).map((accountId): Conversation => ({
            kind: "account",
            id: accountId,
            name: "",
          })),
          ...channels.map((channel): Conversation => ({
            kind: "channel",
            id: channel.channel_id,
            name: channel.name,
          })),
        ],
        identity.history_revision,
        () => lease.current() && get().rosterRequest === request,
      );
      if (!lease.current() || get().rosterRequest !== request || hasPending())
        return;
    }
  } catch {
    // node may still be starting; ignore
  }
}

