      reuseAccounts
        ? Promise.resolve(null)
        : readWithDeadline(() => chat.listAccounts()),
      presenceOnly
        ? Promise.resolve(null)
        : readWithDeadline(() =>
            chat.personalConversationStates(lease.owner!, identity.account_id),
