    fn prepare_recovered_channel_metadata(&self) -> Result<(), super::NodeError> {
        use crate::eventlog::{EventKind, LogError, repository::pages::PageBudget};
        let mut after = None;
        loop {
            let page = self
                .log
                .lock()
                .expect("log mutex")
                .repository()?
                .conversations_page(after.as_ref(), PageBudget::default())?;
